function rampartSimulate(createStrategy, seed, maxTicks, rec) {
  "use strict";
  var TYPES = ["bolt", "cannon", "frost", "lance", "flak"];
  var TS = {
    bolt:   { cost: 50,  dmg: 26,  per: 8,  range: 300, splash: 0,  slow: 0,  pierce: 0, g: 1, a: 1 },
    cannon: { cost: 90,  dmg: 60,  per: 24, range: 260, splash: 90, slow: 0,  pierce: 0, g: 1, a: 0 },
    frost:  { cost: 70,  dmg: 10,  per: 12, range: 240, splash: 0,  slow: 30, pierce: 0, g: 1, a: 1 },
    lance:  { cost: 120, dmg: 180, per: 36, range: 360, splash: 0,  slow: 0,  pierce: 1, g: 1, a: 0 },
    flak:   { cost: 80,  dmg: 40,  per: 10, range: 320, splash: 70, slow: 0,  pierce: 0, g: 0, a: 1 }
  };
  // enemy types: 0 grunt,1 runner,2 wisp,3 brute,4 splitter,5 mender,6 splitling
  var EN = [
    { name: "grunt",     hp: 60,  spd: 10, bounty: 4, leak: 1, air: 0, first: 1, w: 10 },
    { name: "runner",    hp: 40,  spd: 20, bounty: 4, leak: 1, air: 0, first: 2, w: 4 },
    { name: "wisp",      hp: 50,  spd: 12, bounty: 6, leak: 2, air: 1, first: 3, w: 3 },
    { name: "brute",     hp: 150, spd: 6,  bounty: 9, leak: 3, air: 0, first: 4, w: 3 },
    { name: "splitter",  hp: 90,  spd: 8,  bounty: 6, leak: 2, air: 0, first: 6, w: 2 },
    { name: "mender",    hp: 70,  spd: 8,  bounty: 7, leak: 2, air: 0, first: 8, w: 1 },
    { name: "splitling", hp: 0,   spd: 12, bounty: 1, leak: 1, air: 0, first: 999, w: 0 }
  ];
  function mkRoute(pts) {
    var P = [], C = [0], i;
    for (i = 0; i < pts.length; i++) P.push([pts[i][0] * 100 + 50, pts[i][1] * 100 + 50]);
    for (i = 1; i < P.length; i++) C.push(C[i - 1] + Math.abs(P[i][0] - P[i - 1][0]) + Math.abs(P[i][1] - P[i - 1][1]));
    return { P: P, C: C, len: C[C.length - 1] };
  }
  var ROUTES = [
    mkRoute([[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]]),
    mkRoute([[0, 6], [21, 6], [21, 11], [23, 11]])
  ];
  function posAt(r, p) {
    var P = r.P, C = r.C, i = 1;
    if (p <= 0) return [P[0][0], P[0][1]];
    while (i < C.length - 1 && C[i] < p) i++;
    var d = p - C[i - 1], a = P[i - 1], b = P[i];
    var sx = b[0] > a[0] ? 1 : (b[0] < a[0] ? -1 : 0), sy = b[1] > a[1] ? 1 : (b[1] < a[1] ? -1 : 0);
    return [a[0] + sx * d, a[1] + sy * d];
  }
  var SLOTS = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8], [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  var rng = mulberry32(seed);
  var mult = [0, 1000];
  function m(w) { while (mult.length <= w) mult.push(Math.floor(mult[mult.length - 1] * 108 / 100)); return mult[w]; }
  function genWave(w) {
    var n = 4 + Math.floor(3 * w / 5), out = [], i, k;
    var avail = [], tot = 0;
    for (k = 0; k < 6; k++) if (EN[k].first <= w) { avail.push(k); tot += EN[k].w; }
    for (i = 0; i < n; i++) {
      var r = rng() % tot;
      for (k = 0; k < avail.length; k++) { var wt = EN[avail[k]].w; if (r < wt) break; r -= wt; }
      out.push(avail[k]);
    }
    return out;
  }
  var log = [];
  var gold = 250, baseHp = 10, nextId = 1, wave = 0;
  var turrets = new Array(16);
  for (var si = 0; si < 16; si++) turrets[si] = null;
  var enemies = [];
  var queue = [];   // {tick, wave, idx, type}
  var qHead = 0;
  var waves = [null, genWave(1)];
  var strat = createStrategy();
  var fell = false, fallTick = -1, tick;

  function armorFor(t, w) { return t === 0 ? Math.floor(w / 4) : (t === 3 ? 6 + w : 0); }
  function makeEnemy(t, w, hp, prog) {
    var E = EN[t];
    var e = { id: nextId++, t: t, hp: hp, maxHp: hp, prog: prog, armor: armorFor(t, w), spd: E.spd, slow: 0, age: 0, wave: w,
      air: E.air, route: ROUTES[E.air], x: 0, y: 0 };
    var p = posAt(e.route, prog); e.x = p[0]; e.y = p[1];
    return e;
  }
  function view(e) {
    return { id: e.id, type: EN[e.t].name, hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y, air: e.air, armor: e.armor,
      speed: e.spd, slowed: e.slow > 0 ? 1 : 0, remaining: e.route.len - e.prog };
  }
  function tStats(tu) {
    var b = TS[tu.type], d = b.dmg, r = b.range;
    for (var k = 1; k < tu.tier; k++) { d = Math.floor(d * 16 / 10); r += 30; }
    return { dmg: d, range: r };
  }
  function makeState() {
    var sl = [], i, en = [];
    for (i = 0; i < 16; i++) {
      var tu = turrets[i];
      sl.push({ slot: i, x: SLOTS[i][0], y: SLOTS[i][1], turret: tu ? { type: tu.type, tier: tu.tier, spent: tu.spent } : null });
    }
    for (i = 0; i < enemies.length; i++) en.push(view(enemies[i]));
    var nw = [], q = waves[wave + 1];
    for (i = 0; i < q.length; i++) nw.push(EN[q[i]].name);
    return { tick: tick, wave: wave, gold: gold, baseHp: baseHp, slots: sl, enemies: en, nextWave: nw };
  }
  function applyActions(acts) {
    if (!acts || typeof acts.length !== "number") return;
    var n = Math.min(32, acts.length);
    for (var i = 0; i < n; i++) {
      var a = acts[i];
      if (!a || typeof a !== "object") continue;
      var s = a.slot;
      if (typeof s !== "number" || s !== Math.floor(s) || s < 0 || s > 15) continue;
      var tu = turrets[s];
      if (a.op === "build") {
        if (tu || !Object.prototype.hasOwnProperty.call(TS, a.type)) continue;
        var c = TS[a.type].cost;
        if (gold < c) continue;
        gold -= c;
        turrets[s] = { type: a.type, tier: 1, spent: c, cd: 0, x: SLOTS[s][0] * 100 + 50, y: SLOTS[s][1] * 100 + 50 };
        log.push([tick, "B", s, TYPES.indexOf(a.type)]);
        if (rec && rec.action) rec.action(tick, "B", s, a.type, 1);
      } else if (a.op === "upgrade") {
        if (!tu || tu.tier >= 3) continue;
        var uc = TS[tu.type].cost * tu.tier;
        if (gold < uc) continue;
        gold -= uc; tu.spent += uc; tu.tier++;
        log.push([tick, "U", s, tu.tier]);
        if (rec && rec.action) rec.action(tick, "U", s, tu.type, tu.tier);
      } else if (a.op === "sell") {
        if (!tu) continue;
        gold += Math.floor(tu.spent * 70 / 100);
        turrets[s] = null;
        log.push([tick, "S", s, 0]);
        if (rec && rec.action) rec.action(tick, "S", s, tu.type, tu.tier);
      }
    }
  }

  for (tick = 0; tick < maxTicks; tick++) {
    // 1. wave start
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      wave = (tick - 20) / 40 + 1;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * wave;
      waves[wave + 1] = genWave(wave + 1);
      if (rec && rec.waveStart) rec.waveStart(tick, wave, gold);
      applyActions(strat.plan(makeState()));
      var comp = waves[wave];
      for (var qi = 0; qi < comp.length; qi++) queue.push({ tick: tick + 4 * qi, wave: wave, t: comp[qi] });
      queue.sort(function (A, B) { return A.tick - B.tick || A.wave - B.wave; });
      waves[wave - 1] = null;
    }
    // 2. spawn
    while (qHead < queue.length && queue[qHead].tick === tick) {
      var q = queue[qHead++], mw = m(q.wave);
      enemies.push(makeEnemy(q.t, q.wave, Math.floor(EN[q.t].hp * mw / 1000), 0));
    }
    if (qHead > 256) { queue = queue.slice(qHead); qHead = 0; }
    // 3. move
    var keep = [], i, e;
    for (i = 0; i < enemies.length; i++) {
      e = enemies[i];
      e.prog += e.slow > 0 ? Math.floor(e.spd * 60 / 100) : e.spd;
      if (e.prog >= e.route.len) {
        baseHp -= EN[e.t].leak;
        log.push([tick, "L", e.id, baseHp]);
        if (rec && rec.leak) rec.leak(tick, e, baseHp);
        if (baseHp <= 0) {
          fell = true; fallTick = tick;
          log.push([tick, "F", wave, 0]);
          for (var j = i + 1; j < enemies.length; j++) keep.push(enemies[j]);
          break;
        }
        continue;
      }
      var p = posAt(e.route, e.prog); e.x = p[0]; e.y = p[1];
      keep.push(e);
    }
    enemies = keep;
    if (fell) { if (rec && rec.endTick) rec.endTick(tick, enemies, turrets, gold, baseHp, wave); break; }
    // 4. age & heal
    for (i = 0; i < enemies.length; i++) {
      e = enemies[i];
      e.age++;
      if (e.t === 5 && e.age % 20 === 0) {
        for (var h = 0; h < enemies.length; h++) {
          var o = enemies[h], dx = o.x - e.x, dy = o.y - e.y;
          if (dx * dx + dy * dy <= 22500) {
            o.hp = Math.min(o.maxHp, o.hp + Math.floor(o.maxHp * 8 / 100));
          }
        }
        if (rec && rec.heal) rec.heal(tick, e);
      }
    }
    // 5. turrets fire
    for (var s = 0; s < 16; s++) {
      var tu = turrets[s];
      if (!tu) continue;
      if (tu.cd > 0) { tu.cd--; if (tu.cd > 0) continue; }
      var B = TS[tu.type], st = tStats(tu), r2 = st.range * st.range, cands = [];
      for (i = 0; i < enemies.length; i++) {
        e = enemies[i];
        if (e.air ? !B.a : !B.g) continue;
        var ddx = e.x - tu.x, ddy = e.y - tu.y;
        if (ddx * ddx + ddy * ddy <= r2) cands.push(e);
      }
      if (!cands.length) continue;
      var tgt = null;
      if (typeof strat.target === "function") {
        var cv = [];
        for (i = 0; i < cands.length; i++) cv.push(view(cands[i]));
        var tid = strat.target({ slot: s, type: tu.type, tier: tu.tier, x: tu.x, y: tu.y, range: st.range }, cv);
        for (i = 0; i < cands.length; i++) if (cands[i].id === tid) { tgt = cands[i]; break; }
      }
      if (!tgt) {
        tgt = cands[0];
        for (i = 1; i < cands.length; i++) {
          var rr = cands[i].route.len - cands[i].prog, rb = tgt.route.len - tgt.prog;
          if (rr < rb) tgt = cands[i];
        }
      }
      var hitList = [];
      if (B.splash > 0) {
        var sr2 = B.splash * B.splash;
        for (i = 0; i < enemies.length; i++) {
          e = enemies[i];
          if (e.hp <= 0 || (e.air ? !B.a : !B.g)) continue;
          var sx = e.x - tgt.x, sy = e.y - tgt.y;
          if (sx * sx + sy * sy <= sr2) hitList.push(e);
        }
      } else hitList.push(tgt);
      for (i = 0; i < hitList.length; i++) {
        e = hitList[i];
        e.hp -= B.pierce ? st.dmg : Math.max(1, st.dmg - e.armor);
        if (B.slow > 0) e.slow = B.slow;
      }
      tu.cd = B.per;
      if (rec && rec.shot) rec.shot(tick, s, tu, tgt, hitList);
      var anyDead = false;
      for (i = 0; i < enemies.length; i++) if (enemies[i].hp <= 0) { anyDead = true; break; }
      if (anyDead) {
        var alive = [], born = [];
        for (i = 0; i < enemies.length; i++) {
          e = enemies[i];
          if (e.hp > 0) { alive.push(e); continue; }
          gold += EN[e.t].bounty;
          log.push([tick, "K", e.id, s]);
          if (rec && rec.kill) rec.kill(tick, e, s);
          if (e.t === 4) {
            var shp = Math.max(1, Math.floor(e.maxHp / 4));
            for (var k = 0; k < 3; k++) {
              var sp = makeEnemy(6, e.wave, shp, e.prog);
              born.push(sp);
              if (rec && rec.split) rec.split(tick, sp, e);
            }
          }
        }
        enemies = alive.concat(born);
      }
    }
    // 6. slow timers
    for (i = 0; i < enemies.length; i++) if (enemies[i].slow > 0) enemies[i].slow--;
    if (rec && rec.endTick) rec.endTick(tick, enemies, turrets, gold, baseHp, wave);
  }
  var endTick = fell ? fallTick : maxTicks;
  var score = Math.round((endTick - 20) * 10 / 4) / 100;
  var str = JSON.stringify(log), hsh = 0x811c9dc5;
  for (var c = 0; c < str.length; c++) { hsh ^= str.charCodeAt(c); hsh = Math.imul(hsh, 0x01000193); }
  var hex = (hsh >>> 0).toString(16);
  while (hex.length < 8) hex = "0" + hex;
  return { score: score, fallTick: fallTick, log: log, hash: hex };
}

