// Parametrised strategy factory used for tuning. cfg.order: [[op, slot, typeIdx]] op 0 build, 1 upgrade
function makeStrat(cfg) {
  return function createStrategy() {
    var TYPES = ["bolt", "cannon", "frost", "lance", "flak"];
    var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
    var DMG = { bolt: 26, cannon: 60, frost: 10, lance: 180, flak: 40 };
    function mkRoute(pts) {
      var P = [], C = [0], i;
      for (i = 0; i < pts.length; i++) P.push([pts[i][0] * 100 + 50, pts[i][1] * 100 + 50]);
      for (i = 1; i < P.length; i++) C.push(C[i - 1] + Math.abs(P[i][0] - P[i - 1][0]) + Math.abs(P[i][1] - P[i - 1][1]));
      return { P: P, C: C, len: C[C.length - 1] };
    }
    var R = [mkRoute([[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]]), mkRoute([[0, 6], [21, 6], [21, 11], [23, 11]])];
    function pos(e) {
      var r = R[e.air ? 1 : 0], p = r.len - e.remaining, P = r.P, C = r.C, i = 1;
      if (p <= 0) return P[0];
      while (i < C.length - 1 && C[i] < p) i++;
      var d = p - C[i - 1], a = P[i - 1], b = P[i];
      return [a[0] + (b[0] > a[0] ? d : b[0] < a[0] ? -d : 0), a[1] + (b[1] > a[1] ? d : b[1] < a[1] ? -d : 0)];
    }
    function tdmg(type, tier) { var d = DMG[type]; for (var k = 1; k < tier; k++) d = Math.floor(d * 16 / 10); return d; }
    var order = cfg.order, ptr = 0;
    var TG = cfg.tgt || {};
    function eff(e, dmg, pierce) { var d = pierce ? dmg : Math.max(1, dmg - e.armor); return Math.min(d, e.hp); }
    function splashPick(cands, dmg, rad) {
      var best = null, bv = -1, P = [], i, j;
      for (i = 0; i < cands.length; i++) P.push(pos(cands[i]));
      for (i = 0; i < cands.length; i++) {
        var v = 0;
        for (j = 0; j < cands.length; j++) {
          var dx = P[j][0] - P[i][0], dy = P[j][1] - P[i][1];
          if (dx * dx + dy * dy <= rad * rad) v += eff(cands[j], dmg, false);
        }
        v = v * 100000 - cands[i].remaining;
        if (v > bv) { bv = v; best = cands[i]; }
      }
      return best.id;
    }
    return {
      plan: function (s) {
        var acts = [], gold = s.gold, tiers = [], types = [], i;
        for (i = 0; i < 16; i++) { var t = s.slots[i].turret; tiers.push(t ? t.tier : 0); types.push(t ? t.type : null); }
        var reserve = s.wave >= cfg.resW ? cfg.res : 0;
        while (ptr < order.length) {
          var g = order[ptr], sl = g[1], cost;
          if (g[0] === 0) {
            if (tiers[sl] > 0) { ptr++; continue; }
            cost = COST[TYPES[g[2]]];
            if (gold - cost < reserve && !(gold >= cost && s.baseHp < 10 && false)) break;
            acts.push({ op: "build", slot: sl, type: TYPES[g[2]] }); gold -= cost; tiers[sl] = 1; types[sl] = TYPES[g[2]]; ptr++;
          } else {
            if (tiers[sl] === 0 || tiers[sl] >= 3) { ptr++; continue; }
            cost = COST[types[sl]] * tiers[sl];
            if (gold - cost < reserve) break;
            acts.push({ op: "upgrade", slot: sl }); gold -= cost; tiers[sl]++; ptr++;
          }
          if (acts.length >= 32) break;
        }
        return acts;
      },
      target: function (tu, c) {
        var mode = TG[tu.type] || 0, i, best, bv;
        if (mode === 0) return -1;
        var dmg = tdmg(tu.type, tu.tier);
        if (tu.type === "cannon") return splashPick(c, dmg, 90);
        if (tu.type === "flak") return splashPick(c, dmg, 70);
        if (tu.type === "lance") {
          // strongest (max hp), mode 2: first with hp >= dmg else strongest
          best = c[0]; bv = -1;
          for (i = 0; i < c.length; i++) {
            var v = mode === 1 ? c[i].hp * 10000 - c[i].remaining : (c[i].hp >= dmg ? 1e15 - c[i].remaining : c[i].hp);
            if (v > bv) { bv = v; best = c[i]; }
          }
          return best.id;
        }
        if (tu.type === "frost") {
          best = c[0]; bv = -1e18;
          for (i = 0; i < c.length; i++) {
            var fv = (c[i].slowed ? 0 : 1e9) + (mode === 2 ? c[i].hp : 0) * 1000 - c[i].remaining;
            if (fv > bv) { bv = fv; best = c[i]; }
          }
          return best.id;
        }
        if (tu.type === "bolt") {
          best = c[0]; bv = -1e18;
          for (i = 0; i < c.length; i++) {
            var e = eff(c[i], dmg, false);
            var bvv = (mode === 1 ? e : (e * 4 >= dmg * 3 || e === c[i].hp ? 1 : 0)) * 1e7 - c[i].remaining;
            if (bvv > bv) { bv = bvv; best = c[i]; }
          }
          return best.id;
        }
        return -1;
      }
    };
  };
}

