function evalCfg(cfg, seeds) { var t = 0, a = []; for (var i = 0; i < seeds.length; i++) { var r = rampartSimulate(makeStrat(cfg), seeds[i], 12020); t += r.score; a.push(r.score); } return { mean: t / seeds.length, all: a }; }
var seeds = []; for (var i = 1; i <= 12; i++) seeds.push(i * 7919 + 13);
// handcrafted: types 0 bolt 1 cannon 2 frost 3 lance 4 flak
var order = [[0,3,1],[0,1,0],[0,6,1],[0,12,4],[0,2,0],[0,8,1],[0,4,3],[0,11,1],[0,13,3],[0,7,3],[0,0,1],[0,10,0],[0,5,0],[0,14,4],[0,9,3],[0,15,4]];
for (var s = 0; s < 16; s++) order.push([1, s]);
for (var s = 0; s < 16; s++) order.push([1, s]);
var t0 = preciseTime();
var cfgs = [ {order: order, resW: 999, res: 0, tgt: {}}, {order: order, resW: 999, res: 0, tgt: {cannon:1, flak:1, lance:1, frost:1, bolt:2}}, {order: order, resW: 999, res: 0, tgt: {cannon:1, flak:1, lance:2, frost:2, bolt:1}} ];
for (var c of cfgs) { var r = evalCfg(c, seeds); print(r.mean.toFixed(2), JSON.stringify(r.all)); }
print("time", preciseTime() - t0);

