var OPT_SEED = parseInt(arguments[0] || "1"), ITERS = parseInt(arguments[1] || "800"), NS = parseInt(arguments[2] || "20");
var prng = (function (a) { return function () { a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; })(OPT_SEED * 977 + 5);
function ri(n) { return Math.floor(prng() * n); }
var train = []; for (var i = 0; i < NS; i++) train.push(1000 + i * 31337);
function toCfg(L) { var o = []; for (var s = 0; s < 16; s++) o.push([0, s, L.lay[s]]); for (var s = 0; s < 16; s++) o.push([1, s], [1, s]); return { order: o, resW: 999, res: 0, tgt: L.tgt }; }
function ev(L, seeds) { var c = toCfg(L), t = 0; for (var i = 0; i < seeds.length; i++) t += rampartSimulate(makeStrat(c), seeds[i], 12020).score; return t / seeds.length; }
var init = arguments[3] ? JSON.parse(arguments[3]) : { lay: [0,4,4,1,1,1,1,1,1,1,1,1,3,0,0,4], tgt: { cannon: 1, flak: 1, lance: 2, frost: 1, bolt: 2 } };
var cur = init, cs = ev(cur, train), best = cur, bs = cs;
for (var it = 0; it < ITERS; it++) {
  var T = 0.5 * (1 - it / ITERS) + 0.02;
  var n = JSON.parse(JSON.stringify(cur)), k = ri(10);
  if (k < 6) n.lay[ri(16)] = ri(5);
  else if (k < 8) { var a = ri(16), b = ri(16), t = n.lay[a]; n.lay[a] = n.lay[b]; n.lay[b] = t; }
  else { var keys = ["bolt", "lance", "frost", "cannon", "flak"], kk = keys[ri(5)]; n.tgt[kk] = ri(kk === "cannon" || kk === "flak" ? 2 : 3); }
  var ns = ev(n, train);
  if (ns >= cs || prng() < Math.exp((ns - cs) / T)) { cur = n; cs = ns; }
  if (cs > bs) { best = cur; bs = cs; }
  if (it % 100 === 0) print("it", it, cs.toFixed(3), bs.toFixed(3), JSON.stringify(best.lay));
}
var val = []; for (var i = 0; i < 30; i++) val.push(500000 + i * 7777);
print("BEST", bs.toFixed(3), "VAL", ev(best, val).toFixed(3));
print("LAY", JSON.stringify(best));

