load("x_sim.js"); load("x_strategy.js");
var N = parseInt(arguments[0] || "100"), base = parseInt(arguments[1] || "9000001");
var tot = 0, mn = 1e9, mx = 0, tmax = 0, all = [];
for (var i = 0; i < N; i++) {
  var seed = (base + i * 104729) >>> 0, t0 = preciseTime();
  var r = rampartSimulate(createStrategy, seed, 12020);
  var dt = preciseTime() - t0; if (dt > tmax) tmax = dt;
  tot += r.score; mn = Math.min(mn, r.score); mx = Math.max(mx, r.score); all.push(r.score);
}
all.sort(function (a, b) { return a - b; });
var r42 = rampartSimulate(createStrategy, 42, 2020);
print("seeds", N, "mean", (tot / N).toFixed(3), "min", mn, "median", all[N >> 1], "max", mx, "maxGameSec", tmax.toFixed(3));
print("seed42 replay", r42.score, r42.fallTick, r42.hash);
// independence: two strategy objects must not share state
var a = createStrategy(), b = createStrategy(); print("distinct objects", a !== b);

